    createdUser.id,
  );

  TestValidator.equals(
    "session user email should match authenticated user email",
    session.user.email,
    createdUser.email,
  );

  // Step 5: Validate session data integrity through business logic
  TestValidator.predicate(
    "session should have valid relationship data",
    session.user !== null && session.user.id === createdUser.id,
  );

  TestValidator.predicate(
    "session should have proper timestamps",
    new Date(session.created_at).getTime() <= Date.now(),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";
import type { ITodoAppUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUser";
import type { ITodoAppUserSession } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUserSession";

/**
 * Test that authenticated users can permanently delete their own sessions for
 * security purposes.
 *
 * This scenario validates the session deletion functionality including proper
 * authorization checks and prerequisite validation. The test verifies that
 * users can only delete sessions belonging to them and that the deletion
 * successfully removes all session data. Validate that prerequisite todo
 * creation requirements are met before session deletion can proceed. Test the
 * complete workflow from session creation through todo creation to session
 * termination, ensuring proper audit trail and security compliance.
 */
export async function test_api_user_session_force_termination_by_owner(
  connection: api.IConnection,
) {
  // Step 1: Create a new user account to establish authentication context
  const userEmail = typia.random<string & tags.Format<"email">>();
  const userPassword = "testPassword123";

  const createdUser = await api.functional.auth.user.join(connection, {
    body: {
      email: userEmail,
      password: userPassword,
      password_hash: "", // Server will handle hashing
      status: "pending" as const,
      created_at: new Date().toISOString(),
      updated_at: new Date().toISOString(),
    } satisfies ITodoAppUser.ICreate,
  });
  typia.assert(createdUser);

  // Authentication is now established via the join operation which sets headers

  // Step 2: Create a todo item to fulfill prerequisite requirement
  const todoData = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    description: RandomGenerator.content({ paragraphs: 1 }),
    due_date: new Date(Date.now() + 86400000).toISOString(), // Tomorrow
  } satisfies ITodoAppTodo.ICreate;

  const createdTodo = await api.functional.todoApp.user.todos.create(
    connection,
    {
      body: todoData,
    },
  );
  typia.assert(createdTodo);

  // Step 3: Create additional todo for complete prerequisite fulfillment
  const secondTodoData = {
    title: RandomGenerator.paragraph({ sentences: 2 }),
    description: RandomGenerator.content({ paragraphs: 2 }),
  } satisfies ITodoAppTodo.ICreate;

  const secondTodo = await api.functional.todos.create(connection, {
    body: secondTodoData,
  });
  typia.assert(secondTodo);

  // Step 4: Verify session information is available through todo relationships
  TestValidator.predicate(
    "todo should have user session information",
    createdTodo.userSession !== undefined && createdTodo.userSession !== null,
  );

  // Step 5: Extract session ID from the created todo
  const sessionId = typia.assert(createdTodo.userSession!.id);

  // Step 6: Perform session deletion
  await api.functional.todoApp.user.users.sessions.erase(connection, {
    userId: createdUser.id,
    sessionId: sessionId,
  });

  // Step 7: Verify session deletion by creating another todo with fresh session
  const thirdTodoData = {
    title: RandomGenerator.paragraph({ sentences: 4 }),
    description: RandomGenerator.content({ paragraphs: 1 }),
  } satisfies ITodoAppTodo.ICreate;

  const thirdTodo = await api.functional.todoApp.user.todos.create(connection, {
    body: thirdTodoData,
  });
  typia.assert(thirdTodo);

  // Verify the new todo has a different session ID (new session created after deletion)
  TestValidator.notEquals(
    "new todo should have different session ID after deletion",
    thirdTodo.userSession?.id,
    sessionId,
  );

  // Step 8: Test authorization boundary - user cannot delete other users' sessions
  // Create a second user with fresh connection to avoid authentication conflicts
  const secondUserEmail = typia.random<string & tags.Format<"email">>();
  const secondUserPassword = "anotherPassword456";

  const secondUserConnection: api.IConnection = { ...connection, headers: {} };

  const secondUser = await api.functional.auth.user.join(secondUserConnection, {
    body: {
      email: secondUserEmail,
      password: secondUserPassword,
      password_hash: "", // Server will handle hashing
      status: "pending" as const,
      created_at: new Date().toISOString(),
      updated_at: new Date().toISOString(),
    } satisfies ITodoAppUser.ICreate,
  });
  typia.assert(secondUser);

  // Attempt to delete first user's session with second user's connection
  // This should fail due to authorization mismatch
  await TestValidator.error(
    "user cannot delete other user's session",
    async () => {
      await api.functional.todoApp.user.users.sessions.erase(
        secondUserConnection,
        {
          userId: createdUser.id, // First user's ID
          sessionId: sessionId, // Session belongs to first user
        },
      );
    },
  );

  // Step 9: Additional validation - ensure session deletion doesn't affect user functionality
  const fourthTodoData = {
    title: RandomGenerator.paragraph({ sentences: 2 }),
    description: RandomGenerator.content({ paragraphs: 1 }),
  } satisfies ITodoAppTodo.ICreate;

  const fourthTodo = await api.functional.todoApp.user.todos.create(
    connection,
    {
      body: fourthTodoData,
    },
  );
  typia.assert(fourthTodo);

  TestValidator.predicate(
    "user should still be able to create todos after session deletion",
    fourthTodo.id !== undefined,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppTodo";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";
import type { ITodoAppUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUser";
import type { ITodoAppUserSession } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUserSession";

/**
 * Test comprehensive todo search functionality with various filtering options
 * including text search, date range filtering, and pagination.
 *
 * This test validates that users can search their own todos by title keywords,
 * filter by due date ranges, and navigate through paginated results. It ensures
 * that search results respect user isolation boundaries and only return todos
 * owned by the authenticated user.
 */
export async function test_api_todo_search_with_filtering(
  connection: api.IConnection,
) {
  // Step 1: Create authenticated user context
  const userEmail = typia.random<string & tags.Format<"email">>();
  const userPassword = RandomGenerator.alphaNumeric(12);

  const user = await api.functional.auth.user.join(connection, {
    body: {
      email: userEmail,
      password: userPassword,
      password_hash: userPassword, // Using same password for testing
      created_at: new Date().toISOString(),
      updated_at: new Date().toISOString(),
      status: "active" as const,
    } satisfies ITodoAppUser.ICreate,
  });
  typia.assert(user);

  // Step 2: Create multiple todo items with varied data for search testing
  const todos: ITodoAppTodo[] = [];

  // Generate diverse todo data with searchable keywords
  const todoTemplates = [
    { keyword: "project", timeOffset: 86400000 }, // Tomorrow
    { keyword: "review", timeOffset: 172800000 }, // Day after tomorrow
    { keyword: "meeting", timeOffset: -86400000 }, // Yesterday
    { keyword: "documentation", timeOffset: 259200000 }, // 3 days from now
    { keyword: "analysis", timeOffset: 345600000 }, // 4 days from now
  ];

  for (const template of todoTemplates) {
    const todo = await api.functional.todoApp.user.todos.create(connection, {
      body: {
        title: `${RandomGenerator.paragraph({ sentences: 2 })} ${template.keyword}`,
        description: `This todo involves ${template.keyword} work for the ${RandomGenerator.name(1)} project`,
        due_date: new Date(Date.now() + template.timeOffset).toISOString(),
      } satisfies ITodoAppTodo.ICreate,
    });
    typia.assert(todo);
    todos.push(todo);
  }

  // Step 3: Test text search functionality
  const searchResults = await api.functional.todoApp.user.todos.index(
    connection,
    {
      body: {
        search: "project",
      } satisfies ITodoAppTodo.IRequest,
    },
  );
  typia.assert(searchResults);

  TestValidator.predicate(
    "search should return todos containing 'project' keyword",
    searchResults.data.length > 0,
  );

  const foundKeywords = searchResults.data.map(
    (todo) =>
      todo.title.toLowerCase() + " " + (todo.description?.toLowerCase() || ""),
  );
  TestValidator.predicate(
    "search results should contain the search keyword",
    foundKeywords.some((text) => text.includes("project")),
  );

  // Step 4: Test date range filtering
  const currentTime = new Date();
  const tomorrow = new Date(currentTime.getTime() + 86400000).toISOString();
  const futureLimit = new Date(currentTime.getTime() + 604800000).toISOString(); // 7 days from now

  const dateFilterResults = await api.functional.todoApp.user.todos.index(
    connection,
    {
      body: {
        due_after: tomorrow,
        due_before: futureLimit,
      } satisfies ITodoAppTodo.IRequest,
    },
  );
  typia.assert(dateFilterResults);

  TestValidator.predicate(
    "date filter should return future-due todos",
    dateFilterResults.data.length >= 0, // Could be 0 or more
  );

  // Step 5: Test pagination functionality
  const paginationResults = await api.functional.todoApp.user.todos.index(
    connection,
    {
      body: {
        page: 1,
        limit: 3,
      } satisfies ITodoAppTodo.IRequest,
    },
  );
  typia.assert(paginationResults);

  TestValidator.predicate(
    "pagination should return correct number of items",
    paginationResults.data.length <= 3,
  );

  TestValidator.predicate(
    "pagination metadata should be consistent",
    paginationResults.pagination.limit === 3 &&
      paginationResults.pagination.current === 1 &&
      paginationResults.pagination.records >= todos.length &&
      paginationResults.pagination.pages >= 1,
  );

  // Step 6: Test combined search and filtering
  const combinedResults = await api.functional.todoApp.user.todos.index(
    connection,
    {
      body: {
        search: "documentation",
        due_after: new Date().toISOString(), // Current time
        page: 1,
        limit: 10,
      } satisfies ITodoAppTodo.IRequest,
    },
  );
  typia.assert(combinedResults);

  TestValidator.predicate(
    "combined search should return relevant results",
    combinedResults.data.length >= 0, // Could be 0 or more
  );

  // Validate user isolation - todos should belong to the authenticated user
  for (const resultPage of [
    searchResults,
    dateFilterResults,
    paginationResults,
