/**
 * Test search functionality for todo priorities with pagination parameters.
 *
 * This test validates that the API endpoint returns filtered results based on
 * search criteria, proper pagination metadata, and handles various filter
 * combinations including active status and sorting options. It verifies that
 * response includes correct page information and data structure.
 */
export async function test_api_todo_priority_search_pagination(
  connection: api.IConnection,
) {
  // Test 1: Basic pagination with default parameters
  const basicRequest = {
    page: 1,
    limit: 10,
  } satisfies ITodoAppTodoPriority.IRequest;

  const basicResponse: IPageITodoAppTodoPriority.ISummary =
    await api.functional.todoApp.todos.priorities.index(connection, {
      body: basicRequest,
    });
  typia.assert(basicResponse);

  TestValidator.equals(
    "pagination object exists",
    typeof basicResponse.pagination,
    "object",
  );
  TestValidator.predicate(
    "current page is non-negative",
    basicResponse.pagination.current >= 0,
  );
  TestValidator.predicate(
    "limit is non-negative",
    basicResponse.pagination.limit >= 0,
  );
  TestValidator.predicate(
    "total records is non-negative",
    basicResponse.pagination.records >= 0,
  );
  TestValidator.predicate(
    "total pages is non-negative",
    basicResponse.pagination.pages >= 0,
  );

  // Validate pagination calculations
  if (basicResponse.pagination.limit > 0) {
    const expectedPages = Math.ceil(
      basicResponse.pagination.records / basicResponse.pagination.limit,
    );
    TestValidator.equals(
      "pages calculation matches records/limit",
      basicResponse.pagination.pages,
      expectedPages,
    );
  }

  // Test 2: Search by priority code/name
  const searchRequest = {
    page: 1,
    limit: 5,
    search: "high",
  } satisfies ITodoAppTodoPriority.IRequest;

  const searchResponse: IPageITodoAppTodoPriority.ISummary =
    await api.functional.todoApp.todos.priorities.index(connection, {
      body: searchRequest,
    });
  typia.assert(searchResponse);

  // Test 3: Active status filtering
  const activeRequest = {
    page: 1,
    limit: 10,
    is_active: true,
  } satisfies ITodoAppTodoPriority.IRequest;

  const activeResponse: IPageITodoAppTodoPriority.ISummary =
    await api.functional.todoApp.todos.priorities.index(connection, {
      body: activeRequest,
    });
  typia.assert(activeResponse);

  // Test 4: Sorting by weight in ascending order
  const sortAscRequest = {
    page: 1,
    limit: 10,
    order_by: "weight",
    order_direction: "asc",
  } satisfies ITodoAppTodoPriority.IRequest;

  const sortAscResponse: IPageITodoAppTodoPriority.ISummary =
    await api.functional.todoApp.todos.priorities.index(connection, {
      body: sortAscRequest,
    });
  typia.assert(sortAscResponse);

  // Test 5: Sorting by created_at in descending order
  const sortDescRequest = {
    page: 1,
    limit: 10,
    order_by: "created_at",
    order_direction: "desc",
  } satisfies ITodoAppTodoPriority.IRequest;

  const sortDescResponse: IPageITodoAppTodoPriority.ISummary =
    await api.functional.todoApp.todos.priorities.index(connection, {
      body: sortDescRequest,
    });
  typia.assert(sortDescResponse);

  // Test 6: Combination of multiple filters
  const combinedRequest = {
    page: 1,
    limit: 5,
    search: "urgent",
    is_active: true,
    order_by: "weight",
    order_direction: "desc",
  } satisfies ITodoAppTodoPriority.IRequest;

  const combinedResponse: IPageITodoAppTodoPriority.ISummary =
    await api.functional.todoApp.todos.priorities.index(connection, {
      body: combinedRequest,
    });
  typia.assert(combinedResponse);

  // Test 7: Random parameter combinations
  const randomRequest = typia.random<ITodoAppTodoPriority.IRequest>();
  const randomResponse: IPageITodoAppTodoPriority.ISummary =
    await api.functional.todoApp.todos.priorities.index(connection, {
      body: randomRequest,
    });
  typia.assert(randomResponse);

  // Test 8: Edge case - page beyond total pages
  const highPageRequest = {
    page: 1000,
    limit: 10,
  } satisfies ITodoAppTodoPriority.IRequest;

  const highPageResponse: IPageITodoAppTodoPriority.ISummary =
    await api.functional.todoApp.todos.priorities.index(connection, {
      body: highPageRequest,
    });
  typia.assert(highPageResponse);

  // Validate data structure for responses with data
  if (basicResponse.data.length > 0) {
    const priority = basicResponse.data[0];
    TestValidator.predicate(
      "priority has UUID id",
      typeof priority.id === "string" && priority.id.length > 0,
    );
    TestValidator.predicate(
      "priority has code string",
      typeof priority.code === "string" && priority.code.length > 0,
    );
    TestValidator.predicate(
      "priority has name string",
      typeof priority.name === "string" && priority.name.length > 0,
    );
    TestValidator.predicate(
      "priority has valid weight",
      typeof priority.weight === "number" &&
        priority.weight >= 1 &&
        priority.weight <= 100,
    );
    TestValidator.predicate(
      "priority has ISO date string",
      typeof priority.created_at === "string" &&
        priority.created_at.includes("T"),
    );

    if (priority.description !== undefined) {
      TestValidator.predicate(
        "optional description is string",
        typeof priority.description === "string",
      );
    }

    if (priority.is_active !== undefined) {
      TestValidator.predicate(
        "optional is_active is boolean",
        typeof priority.is_active === "boolean",
      );
    }
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppTodo";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";
import type { ITodoAppUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUser";
import type { ITodoAppUserSession } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUserSession";

/**
 * Test the basic search functionality for todo items using various filter
 * combinations.
 *
 * This test validates the search API by creating multiple todo items with
 * diverse attributes and testing different search scenarios including text
 * search, date range filtering, and pagination controls. The test ensures that
 * search results correctly filter todos based on the authenticated user's
 * ownership and respect all provided search parameters.
 */
export async function test_api_todo_search_basic_filtering(
  connection: api.IConnection,
) {
  // 1. Create a new user account for authentication
  const userEmail = typia.random<string & tags.Format<"email">>();
  const userPassword = "testPassword123";

  const user = await api.functional.auth.user.join(connection, {
    body: {
      email: userEmail,
      password: userPassword,
      password_hash: userPassword, // Server will hash this properly
      status: "pending" as const,
      created_at: new Date().toISOString(),
      updated_at: new Date().toISOString(),
      deleted_at: undefined,
    } satisfies ITodoAppUser.ICreate,
  });
  typia.assert(user);

  // 2. Create multiple todo items with varied attributes for search testing
  const todos = await ArrayUtil.asyncRepeat(5, async (index) => {
    const dueDate =
      index % 2 === 0
        ? new Date(Date.now() + (index + 1) * 86400000).toISOString() // Future dates
        : undefined;

    const todo = await api.functional.todos.create(connection, {
      body: {
        title: `Todo ${index + 1} ${index % 2 === 0 ? "urgent" : "normal"}`,
        description:
          index % 3 === 0
            ? `This is a detailed description for todo ${index + 1} with important notes`
            : undefined,
        due_date: dueDate,
      } satisfies ITodoAppTodo.ICreate,
    });
    typia.assert(todo);
    return todo;
  });

  // 3. Test basic search without filters (should return all todos)
  const allTodosResult = await api.functional.todos.search(connection, {
    body: {} satisfies ITodoAppTodo.IRequest,
  });
  typia.assert(allTodosResult);
  TestValidator.equals(
    "should return all created todos",
    allTodosResult.data.length,
    todos.length,
  );

  // 4. Test text search in titles
  const titleSearchResult = await api.functional.todos.search(connection, {
    body: {
      search: "urgent",
    } satisfies ITodoAppTodo.IRequest,
  });
  typia.assert(titleSearchResult);
  TestValidator.predicate(
    "should find todos with 'urgent' in title",
    titleSearchResult.data.length > 0 &&
      titleSearchResult.data.every((todo) => todo.title.includes("urgent")),
  );

  // 5. Test text search in descriptions
  const descriptionSearchResult = await api.functional.todos.search(
    connection,
    {
      body: {
        search: "detailed description",
      } satisfies ITodoAppTodo.IRequest,
    },
  );
  typia.assert(descriptionSearchResult);
  TestValidator.predicate(
    "should find todos with 'detailed description' in description",
    descriptionSearchResult.data.length > 0 &&
      descriptionSearchResult.data.every(
        (todo) => todo.description?.includes("detailed description") ?? false,
      ),
  );

  // 6. Test date range filtering (only for todos with due dates)
  const todosWithDueDates = todos.filter((todo) => todo.due_date !== undefined);
  if (todosWithDueDates.length > 0) {
    const earliestDueDate = todosWithDueDates.reduce(
      (earliest, todo) =>
        todo.due_date! < earliest ? todo.due_date! : earliest,
      todosWithDueDates[0].due_date!,
    );

    const dateSearchResult = await api.functional.todos.search(connection, {
      body: {
        due_after: earliestDueDate,
      } satisfies ITodoAppTodo.IRequest,
    });
    typia.assert(dateSearchResult);
    TestValidator.predicate(
      "should find todos with due dates after earliest date",
      dateSearchResult.data.length >= todosWithDueDates.length,
    );
  }

  // 7. Test pagination controls
  const paginatedResult = await api.functional.todos.search(connection, {
    body: {
      page: 1,
      limit: 2,
    } satisfies ITodoAppTodo.IRequest,
  });
  typia.assert(paginatedResult);
  TestValidator.equals(
    "should return exactly 2 items per page",
    paginatedResult.data.length,
    2,
  );
  TestValidator.predicate(
    "pagination metadata should be correct",
    paginatedResult.pagination.current === 1 &&
      paginatedResult.pagination.limit === 2 &&
      paginatedResult.pagination.records >= todos.length &&
      paginatedResult.pagination.pages >= Math.ceil(todos.length / 2),
  );

  // 8. Test combined search with multiple filters
  const combinedSearchResult = await api.functional.todos.search(connection, {
    body: {
      search: "todo",
      limit: 10,
    } satisfies ITodoAppTodo.IRequest,
  });
  typia.assert(combinedSearchResult);
  TestValidator.predicate(
    "combined search should return relevant results",
    combinedSearchResult.data.length > 0 &&
      combinedSearchResult.data.every((todo) => todo.title.includes("todo")),
  );

  // 9. Test empty search result scenario
  const noMatchSearchResult = await api.functional.todos.search(connection, {
    body: {
      search: "nonexistentkeyword12345",
    } satisfies ITodoAppTodo.IRequest,
  });
  typia.assert(noMatchSearchResult);
  TestValidator.equals(
    "should return empty results for non-matching search",
    noMatchSearchResult.data.length,
    0,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppTodo";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";
import type { ITodoAppUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUser";
import type { ITodoAppUserSession } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUserSession";

/**
 * Test search functionality when no todos match the specified criteria.
 *
 * This test validates that the todo search API correctly handles scenarios
 * where search criteria exclude all existing todo items. It creates a baseline
 * of todo items with specific attributes and then performs searches with
 * filters that intentionally don't match any of the created items, ensuring the
 * system returns proper empty results with correct pagination metadata.
 *
 * Step-by-step process:
 *
 * 1. Create a new user account and authenticate
 * 2. Create multiple todo items with specific content
 * 3. Execute search queries with non-matching criteria
 * 4. Validate empty results with proper pagination
 * 5. Test various restrictive filter scenarios
 */
export async function test_api_todo_search_empty_results(
  connection: api.IConnection,
) {
  // Step 1: Create a new user account for authentication
  const userEmail = typia.random<string & tags.Format<"email">>();
  const user = await api.functional.auth.user.join(connection, {
    body: {
      email: userEmail,
      password: "testPassword123",
      password_hash: "hashed_password_placeholder",
      created_at: new Date().toISOString(),
      updated_at: new Date().toISOString(),
    } satisfies ITodoAppUser.ICreate,
  });
  typia.assert(user);

  // Step 2: Create test todo items with specific content
  const todos = await ArrayUtil.asyncRepeat(3, async (index) => {
    const todo = await api.functional.todos.create(connection, {
      body: {
        title: `Test Todo ${index + 1}`,
        description: `This is test todo item number ${index + 1}`,
        due_date: new Date(
          Date.now() + 86400000 * (index + 1),
        ).toISOString() satisfies
          | (string & tags.Format<"date-time">)
          | undefined as (string & tags.Format<"date-time">) | undefined,
      } satisfies ITodoAppTodo.ICreate,
    });
    typia.assert(todo);
    return todo;
  });

  // Step 3: Execute search queries with filters that exclude all todos

  // Test 1: Search for non-existent content
  const searchResult1 = await api.functional.todos.search(connection, {
    body: {
      search: "nonexistent_keyword_that_does_not_exist_in_any_todo",
      page: 1,
      limit: 10,
    } satisfies ITodoAppTodo.IRequest,
  });
  typia.assert(searchResult1);

  // Validate empty results with proper pagination
  TestValidator.equals(
    "search with completely non-existent keyword returns empty data",
    searchResult1.data,
    [],
  );
  TestValidator.equals(
    "pagination current page should be 1 for non-existent keyword search",
    searchResult1.pagination.current,
    1,
  );
  TestValidator.equals(
    "pagination limit should be 10 for non-existent keyword search",
    searchResult1.pagination.limit,
    10,
  );
  TestValidator.equals(
    "total records should be 0 for non-existent keyword search",
    searchResult1.pagination.records,
    0,
  );
  TestValidator.equals(
    "total pages should be 0 for non-existent keyword search",
    searchResult1.pagination.pages,
    0,
  );

  // Test 2: Search with due date filter that excludes all todos
  const pastDate = new Date(Date.now() - 86400000).toISOString(); // Yesterday
  const searchResult2 = await api.functional.todos.search(connection, {
    body: {
      due_before: pastDate satisfies
        | (string & tags.Format<"date-time">)
        | undefined as (string & tags.Format<"date-time">) | undefined,
      page: 1,
      limit: 5,
    } satisfies ITodoAppTodo.IRequest,
  });
  typia.assert(searchResult2);

  // Validate empty results
  TestValidator.equals(
    "search with past due date filter returns empty data",
    searchResult2.data,
    [],
  );
  TestValidator.equals(
    "pagination current page should be 1 for past date search",
    searchResult2.pagination.current,
    1,
  );
  TestValidator.equals(
    "pagination limit should be 5 for past date search",
    searchResult2.pagination.limit,
    5,
  );
  TestValidator.equals(
    "total records should be 0 for past date search",
    searchResult2.pagination.records,
    0,
  );

  // Test 3: Search with combination of filters that exclude all
  const searchResult3 = await api.functional.todos.search(connection, {
    body: {
      search: "completely_different_content_not_found_in_todos",
      due_after: new Date(Date.now() + 86400000 * 10).toISOString() satisfies
        | (string & tags.Format<"date-time">)
        | undefined as (string & tags.Format<"date-time">) | undefined,
      page: 1,
      limit: 20,
    } satisfies ITodoAppTodo.IRequest,
  });
  typia.assert(searchResult3);

  // Validate empty results
  TestValidator.equals(
    "search with combination of non-matching filters returns empty data",
    searchResult3.data,
    [],
  );
  TestValidator.equals(
    "pagination current page should be 1 for combined filter search",
    searchResult3.pagination.current,
    1,
  );
  TestValidator.equals(
    "pagination limit should be 20 for combined filter search",
    searchResult3.pagination.limit,
    20,
  );
  TestValidator.equals(
    "total records should be 0 for combined filter search",
    searchResult3.pagination.records,
    0,
  );

  // Test 4: Search with empty criteria but high page number
  const searchResult4 = await api.functional.todos.search(connection, {
    body: {
      page: 100,
      limit: 10,
    } satisfies ITodoAppTodo.IRequest,
  });
  typia.assert(searchResult4);

  // Validate empty results for out-of-range page
  TestValidator.equals(
    "search with high page number beyond data range returns empty data",
    searchResult4.data,
    [],
  );
  TestValidator.equals(
    "pagination current page should be 100 for high page search",
    searchResult4.pagination.current,
    100,
  );
  TestValidator.equals(
    "pagination limit should be 10 for high page search",
    searchResult4.pagination.limit,
    10,
  );
  TestValidator.equals(
    "total records should be 0 for high page search",
    searchResult4.pagination.records,
    0,
  );

  // Test 5: Search with impossible date range combination
  const searchResult5 = await api.functional.todos.search(connection, {
    body: {
      due_before: new Date(Date.now() - 86400000).toISOString() satisfies
        | (string & tags.Format<"date-time">)
        | undefined as (string & tags.Format<"date-time">) | undefined,
      due_after: new Date(Date.now() + 86400000).toISOString() satisfies
        | (string & tags.Format<"date-time">)
        | undefined as (string & tags.Format<"date-time">) | undefined,
      page: 1,
      limit: 15,
    } satisfies ITodoAppTodo.IRequest,
  });
  typia.assert(searchResult5);

  // Validate empty results for impossible date range
  TestValidator.equals(
    "search with impossible date range returns empty data",
    searchResult5.data,
    [],
  );
  TestValidator.equals(
    "pagination current page should be 1 for impossible range search",
    searchResult5.pagination.current,
    1,
  );
  TestValidator.equals(
    "pagination limit should be 15 for impossible range search",
    searchResult5.pagination.limit,
    15,
  );
  TestValidator.equals(
    "total records should be 0 for impossible range search",
    searchResult5.pagination.records,
    0,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppTodo";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";
import type { ITodoAppUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUser";
import type { ITodoAppUserSession } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUserSession";

/**
 * Validate pagination functionality by creating a large number of todo items
 * and verifying that search results are correctly paginated.
 *
 * This test creates a new user account, authenticates, generates 25 todo items
 * exceeding default pagination limits, and tests various pagination scenarios
 * including different page sizes and boundary conditions.
 */
export async function test_api_todo_search_pagination_controls(
  connection: api.IConnection,
) {
  // Step 1: Create and authenticate a new user
  const userEmail = typia.random<string & tags.Format<"email">>();
  const userPassword = "testPassword123";

  const user = await api.functional.auth.user.join(connection, {
    body: {
      email: userEmail,
      password: userPassword,
      password_hash: "", // Will be hashed by server
      status: "active",
      created_at: new Date().toISOString(),
      updated_at: new Date().toISOString(),
      deleted_at: undefined,
    } satisfies ITodoAppUser.ICreate,
  });
  typia.assert(user);

  // Step 2: Create 25 todo items to exceed default pagination limits
  const todos = await ArrayUtil.asyncRepeat(25, async (index) => {
    const todo = await api.functional.todos.create(connection, {
      body: {
        title: RandomGenerator.paragraph({
          sentences: 3,
          wordMin: 3,
          wordMax: 8,
        }),
        description: RandomGenerator.content({
          paragraphs: 1,
          sentenceMin: 2,
          sentenceMax: 5,
        }),
        due_date: undefined,
      } satisfies ITodoAppTodo.ICreate,
    });
    typia.assert(todo);
    return todo;
  });

  // Step 3: Test pagination with limit of 5 items per page
  const pageSize5 = 5;
  const totalPages5 = Math.ceil(todos.length / pageSize5);

  // Test first page
  const page1Result = await api.functional.todos.search(connection, {
    body: {
      page: 1,
      limit: pageSize5,
    } satisfies ITodoAppTodo.IRequest,
  });
  typia.assert(page1Result);

  TestValidator.equals(
    "first page current should be 1",
    page1Result.pagination.current,
    1,
  );
  TestValidator.equals(
    "first page limit should match request",
    page1Result.pagination.limit,
    pageSize5,
  );
  TestValidator.equals(
    "first page total records should match created todos",
    page1Result.pagination.records,
    todos.length,
  );
  TestValidator.equals(
    "first page total pages should be correct",
    page1Result.pagination.pages,
    totalPages5,
  );
  TestValidator.equals(
    "first page should have full limit items",
    page1Result.data.length,
    pageSize5,
  );

  // Test middle page
  const middlePage = Math.floor(totalPages5 / 2);
  const middlePageResult = await api.functional.todos.search(connection, {
    body: {
      page: middlePage,
      limit: pageSize5,
    } satisfies ITodoAppTodo.IRequest,
  });
  typia.assert(middlePageResult);

  TestValidator.equals(
    "middle page current should match request",
    middlePageResult.pagination.current,
    middlePage,
  );
  TestValidator.equals(
    "middle page limit should match request",
    middlePageResult.pagination.limit,
    pageSize5,
  );
  TestValidator.equals(
    "middle page total records should be consistent",
    middlePageResult.pagination.records,
    todos.length,
  );
  TestValidator.equals(
    "middle page total pages should be consistent",
    middlePageResult.pagination.pages,
    totalPages5,
  );
  TestValidator.equals(
    "middle page should have full limit items",
    middlePageResult.data.length,
    pageSize5,
  );

  // Test last page
  const lastPageResult = await api.functional.todos.search(connection, {
    body: {
      page: totalPages5,
      limit: pageSize5,
    } satisfies ITodoAppTodo.IRequest,
  });
  typia.assert(lastPageResult);

  TestValidator.equals(
    "last page current should match request",
    lastPageResult.pagination.current,
    totalPages5,
  );
  TestValidator.equals(
    "last page limit should match request",
    lastPageResult.pagination.limit,
    pageSize5,
  );
  TestValidator.equals(
    "last page total records should be consistent",
    lastPageResult.pagination.records,
    todos.length,
  );
  TestValidator.equals(
    "last page total pages should be consistent",
    lastPageResult.pagination.pages,
    totalPages5,
  );

  const expectedLastPageItems = todos.length % pageSize5 || pageSize5;
  TestValidator.equals(
    "last page should have correct item count",
    lastPageResult.data.length,
    expectedLastPageItems,
  );

  // Step 4: Test pagination with limit of 10 items per page
  const pageSize10 = 10;
  const totalPages10 = Math.ceil(todos.length / pageSize10);

  const page1Result10 = await api.functional.todos.search(connection, {
    body: {
      page: 1,
      limit: pageSize10,
    } satisfies ITodoAppTodo.IRequest,
  });
  typia.assert(page1Result10);

  TestValidator.equals(
    "page 1 with limit 10 current should be 1",
    page1Result10.pagination.current,
    1,
  );
  TestValidator.equals(
    "page 1 with limit 10 limit should match",
    page1Result10.pagination.limit,
    pageSize10,
  );
  TestValidator.equals(
    "page 1 with limit 10 total records should be consistent",
    page1Result10.pagination.records,
    todos.length,
  );
  TestValidator.equals(
    "page 1 with limit 10 total pages should be correct",
    page1Result10.pagination.pages,
    totalPages10,
  );
  TestValidator.equals(
    "page 1 with limit 10 should have full limit items",
    page1Result10.data.length,
    pageSize10,
  );

  // Step 5: Test pagination with limit larger than total items
  const largeLimitResult = await api.functional.todos.search(connection, {
    body: {
      page: 1,
      limit: 100,
    } satisfies ITodoAppTodo.IRequest,
  });
  typia.assert(largeLimitResult);

  TestValidator.equals(
    "large limit current should be 1",
    largeLimitResult.pagination.current,
    1,
  );
  TestValidator.equals(
    "large limit should match request",
    largeLimitResult.pagination.limit,
    100,
  );
  TestValidator.equals(
    "large limit total records should be consistent",
    largeLimitResult.pagination.records,
    todos.length,
  );
  TestValidator.equals(
    "large limit total pages should be 1",
    largeLimitResult.pagination.pages,
    1,
  );
  TestValidator.equals(
    "large limit should return all items",
    largeLimitResult.data.length,
    todos.length,
  );

  // Step 6: Test default pagination (no parameters)
  const defaultResult = await api.functional.todos.search(connection, {
    body: {} satisfies ITodoAppTodo.IRequest,
  });
  typia.assert(defaultResult);

  TestValidator.predicate(
    "default pagination should return results",
    defaultResult.data.length > 0,
  );
  TestValidator.predicate(
    "default pagination should have valid current page",
    defaultResult.pagination.current === 1,
  );
  TestValidator.predicate(
    "default pagination should have positive limit",
    defaultResult.pagination.limit > 0,
  );
  TestValidator.predicate(
    "default pagination should have correct total records",
    defaultResult.pagination.records === todos.length,
  );
  TestValidator.predicate(
    "default pagination should have valid total pages",
    defaultResult.pagination.pages > 0,
  );

  // Step 7: Test error handling for out-of-bounds page
  await TestValidator.error("page number 0 should fail", async () => {
    await api.functional.todos.search(connection, {
      body: {
        page: 0,
        limit: pageSize5,
      } satisfies ITodoAppTodo.IRequest,
    });
  });

  await TestValidator.error("page beyond total pages should fail", async () => {
    await api.functional.todos.search(connection, {
      body: {
        page: totalPages5 + 10,
        limit: pageSize5,
      } satisfies ITodoAppTodo.IRequest,
    });
  });
}

