import { ITodoAppUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUser";
import { UserPayload } from "../decorators/payload/UserPayload";

export async function getTodoAppUserUsersUserId(props: {
  user: UserPayload;
  userId: string & tags.Format<"uuid">;
}): Promise<ITodoAppUser> {
  const userRecord = await MyGlobal.prisma.todo_app_users.findUnique({
    where: { id: props.userId },
  });

  if (!userRecord) {
    throw new HttpException("User not found", 404);
  }

  if (userRecord.deleted_at !== null) {
    throw new HttpException("User account has been deleted", 404);
  }

  return {
    id: userRecord.id,
    email: userRecord.email,
    password_hash: userRecord.password_hash,
    status: typia.assert<"pending" | "active" | "suspended">(userRecord.status),
    created_at: toISOStringSafe(userRecord.created_at),
    updated_at: toISOStringSafe(userRecord.updated_at),
    deleted_at: userRecord.deleted_at
      ? toISOStringSafe(userRecord.deleted_at)
      : undefined,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";
import { IPageITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppTodo";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { ITodoAppUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUser";
import { ITodoAppUserSession } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUserSession";
import { UserPayload } from "../decorators/payload/UserPayload";

export async function patchTodoAppUserTodos(props: {
  user: UserPayload;
  body: ITodoAppTodo.IRequest;
}): Promise<IPageITodoAppTodo.ISummary> {
  // Validate pagination parameters
  const page = Math.max(1, props.body.page ?? 1);
  const limit = Math.max(1, Math.min(100, props.body.limit ?? 100));
  const skip = (page - 1) * limit;

  // Build where conditions
  const whereConditions: Prisma.todo_app_todosWhereInput = {
    todo_app_user_id: props.user.id,
    deleted_at: null,
  };

  // Add text search if provided
  if (props.body.search && props.body.search.trim().length > 0) {
    whereConditions.OR = [
      { title: { contains: props.body.search } },
      { description: { contains: props.body.search } },
    ];
  }

  // Add due date filtering
  if (props.body.due_before || props.body.due_after) {
    whereConditions.due_date = {};

    if (props.body.due_before) {
      whereConditions.due_date.lte = props.body.due_before;
    }

    if (props.body.due_after) {
      whereConditions.due_date.gte = props.body.due_after;
    }
  }

  try {
    // Execute queries concurrently
    const [data, total] = await Promise.all([
      MyGlobal.prisma.todo_app_todos.findMany({
        where: whereConditions,
        skip,
        take: limit,
        orderBy: { created_at: "desc" },
        include: {
          user: true,
          userSession: true,
        },
      }),
      MyGlobal.prisma.todo_app_todos.count({
        where: whereConditions,
      }),
    ]);

    // Transform results with proper type flow
    const transformedData: ITodoAppTodo.ISummary[] = data.map((todo) => ({
      id: todo.id,
      user: {
        id: todo.user.id,
        email: todo.user.email,
        status: todo.user.status,
        created_at: toISOStringSafe(todo.user.created_at),
      },
      session: todo.userSession
        ? {
            id: todo.userSession.id,
            ip: todo.userSession.ip,
            href: todo.userSession.href,
            referrer: todo.userSession.referrer,
            created_at: toISOStringSafe(todo.userSession.created_at),
            expired_at: todo.userSession.expired_at
              ? toISOStringSafe(todo.userSession.expired_at)
              : toISOStringSafe(new Date(0)), // Provide default value when expired_at is null/undefined
          }
        : undefined,
      title: todo.title,
      description: todo.description ?? undefined,
      due_date: todo.due_date ? toISOStringSafe(todo.due_date) : undefined,
      created_at: toISOStringSafe(todo.created_at),
      updated_at: toISOStringSafe(todo.updated_at),
      deleted_at: todo.deleted_at
        ? toISOStringSafe(todo.deleted_at)
        : undefined,
    }));

    return {
      pagination: {
        current: page,
        limit: limit,
        records: total,
        pages: Math.ceil(total / limit),
      },
      data: transformedData,
    };
  } catch (error) {
    throw new HttpException("Failed to retrieve todo items", 500);
  }
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoAppUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUser";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";

export async function postAuthUserJoin(props: {
  body: ITodoAppUser.ICreate;
}): Promise<ITodoAppUser.IAuthorized> {
  // Check for existing user with same email
  const existingUser = await MyGlobal.prisma.todo_app_users.findUnique({
    where: {
      email: props.body.email,
    },
  });

  if (existingUser) {
    throw new HttpException("Email already registered", 409);
  }

  // Hash the password using PasswordUtil (ignore password_hash from body)
  const hashedPassword = await PasswordUtil.hash(props.body.password);

  const userId = v4() as string & tags.Format<"uuid">;
  const currentTime = toISOStringSafe(new Date());

  // Calculate expiration times without Date objects
  const currentTimeMillis = Date.now();
  const accessExpiresMillis = currentTimeMillis + 60 * 60 * 1000; // 1 hour
  const refreshExpiresMillis = currentTimeMillis + 7 * 24 * 60 * 60 * 1000; // 7 days

  const accessExpires = toISOStringSafe(new Date(accessExpiresMillis));
  const refreshExpires = toISOStringSafe(new Date(refreshExpiresMillis));

  // Create the user (actor) record
  const user = await MyGlobal.prisma.todo_app_users.create({
    data: {
      id: userId,
      email: props.body.email,
      password_hash: hashedPassword, // Use the hashed password, not from body
      status: "pending",
      created_at: currentTime,
      updated_at: currentTime,
      deleted_at: null,
    },
  });

  const sessionId = v4() as string & tags.Format<"uuid">;

  // Create session record with default values (since session context not provided)
  const session = await MyGlobal.prisma.todo_app_user_sessions.create({
    data: {
      id: sessionId,
      todo_app_user_id: userId,
      ip: "127.0.0.1", // Default IP since not provided in current props structure
      href: "/", // Default URL
      referrer: "", // Default referrer
      created_at: currentTime,
      expired_at: accessExpires,
    },
  });

  // Generate JWT tokens
  const token = {
    access: jwt.sign(
      {
        type: "user",
        id: userId,
        session_id: sessionId,
        created_at: currentTime,
      },
      MyGlobal.env.JWT_SECRET_KEY,
      {
        expiresIn: "1h",
        issuer: "autobe",
      },
    ),
    refresh: jwt.sign(
      {
        type: "user",
        id: userId,
        session_id: sessionId,
        tokenType: "refresh",
        created_at: currentTime,
      },
      MyGlobal.env.JWT_SECRET_KEY,
      {
        expiresIn: "7d",
        issuer: "autobe",
      },
    ),
    expired_at: accessExpires,
    refreshable_until: refreshExpires,
  };

  // Return authorized user information
  return {
    id: userId,
    email: user.email,
    password_hash: user.password_hash,
    status: typia.assert<"pending" | "active" | "suspended">(user.status),
    created_at: toISOStringSafe(user.created_at),
    updated_at: toISOStringSafe(user.updated_at),
    deleted_at:
      user.deleted_at === null ? undefined : toISOStringSafe(user.deleted_at),
    token,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoAppUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUser";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";

export async function postAuthUserLogin(props: {
  body: ITodoAppUser.ICredentials;
}): Promise<ITodoAppUser.IAuthorized> {
  // Step 1: Find user by email
  const user = await MyGlobal.prisma.todo_app_users.findFirst({
    where: { email: props.body.email },
  });

  if (!user) {
    throw new HttpException("Invalid credentials", 401);
  }

  // Step 2: Check account status before password verification for security
  if (user.status === "suspended") {
    throw new HttpException("Account is suspended", 403);
  }
  if (user.status === "pending") {
    throw new HttpException("Account pending verification", 403);
  }

  // Step 3: Verify password
  const isValid = await PasswordUtil.verify(
    props.body.password,
    user.password_hash,
  );

  if (!isValid) {
    throw new HttpException("Invalid credentials", 401);
  }

  // Step 4: Create session record using string timestamps
  const currentTime = new Date().toISOString();
  const accessExpiresMs = Date.now() + 60 * 60 * 1000;
  const refreshExpiresMs = Date.now() + 7 * 24 * 60 * 60 * 1000;

  const session = await MyGlobal.prisma.todo_app_user_sessions.create({
    data: {
      id: v4(),
      todo_app_user_id: user.id,
      ip: props.body.ip ?? "", // Schema shows ip is required string, so use empty string as fallback
      href: props.body.href,
      referrer: props.body.referrer,
      created_at: currentTime,
      expired_at: new Date(accessExpiresMs).toISOString(),
    },
  });

  // Step 5: Generate JWT tokens with proper payload structure
  const tokenPayload = {
    type: "user" as const,
    id: user.id,
    session_id: session.id,
    created_at: currentTime,
  };

  const refreshPayload = {
    ...tokenPayload,
    tokenType: "refresh" as const,
  };

  const token = {
    access: jwt.sign(tokenPayload, MyGlobal.env.JWT_SECRET_KEY, {
      expiresIn: "1h",
      issuer: "autobe",
    }),
    refresh: jwt.sign(refreshPayload, MyGlobal.env.JWT_SECRET_KEY, {
      expiresIn: "7d",
      issuer: "autobe",
    }),
    expired_at: new Date(accessExpiresMs).toISOString(),
    refreshable_until: new Date(refreshExpiresMs).toISOString(),
  };

  // Step 6: Return authorized user information with proper type conversions
  return {
    id: user.id,
    email: user.email,
    password_hash: user.password_hash,
    status: typia.assert<"pending" | "active" | "suspended">(user.status),
    created_at: toISOStringSafe(user.created_at),
    updated_at: toISOStringSafe(user.updated_at),
    deleted_at: user.deleted_at ? toISOStringSafe(user.deleted_at) : undefined,
    token,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoAppTodoDashboard } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoDashboard";
import { IPriorityDistribution } from "@ORGANIZATION/PROJECT-api/lib/structures/IPriorityDistribution";
import { UserPayload } from "../decorators/payload/UserPayload";

export async function getTodoAppUserDashboardTodoOverview(props: {
  user: UserPayload;
}): Promise<ITodoAppTodoDashboard> {
  const userId = props.user.id;
  const now = toISOStringSafe(new Date());
  const sevenDaysAgo = toISOStringSafe(
    new Date(Date.now() - 7 * 24 * 60 * 60 * 1000),
  );
  const sevenDaysLater = toISOStringSafe(
    new Date(Date.now() + 7 * 24 * 60 * 60 * 1000),
  );

  // Get active status and priority codes
  const [statuses, priorities] = await Promise.all([
    MyGlobal.prisma.todo_app_todo_statuses.findMany({
      where: { is_active: true },
    }),
    MyGlobal.prisma.todo_app_todo_priorities.findMany({
      where: { is_active: true },
    }),
  ]);

  const statusMap = statuses.reduce(
    (acc, status) => {
      acc[status.code] = status.id;
      return acc;
    },
    {} as Record<string, string>,
  );

  const priorityMap = priorities.reduce(
    (acc, priority) => {
      acc[priority.code] = priority.id;
      return acc;
    },
    {} as Record<string, string>,
  );

  // Verify required status codes exist
  if (!statusMap.pending || !statusMap["in-progress"] || !statusMap.completed) {
    throw new HttpException("Required todo status codes not found", 500);
  }

  // Base where condition for user's active todos
  const baseWhere = {
    todo_app_user_id: userId,
    deleted_at: null,
  };

  // Execute all metric queries concurrently
  const [
    totalTodos,
    completedTodos,
    pendingTodos,
    inProgressTodos,
    overdueTodos,
    priorityDistribution,
    recentCompletions,
    upcomingDueDates,
    averageCompletionData,
  ] = await Promise.all([
    // Total todos
    MyGlobal.prisma.todo_app_todos.count({ where: baseWhere }),

    // Completed todos
    MyGlobal.prisma.todo_app_todo_lifecycles.count({
      where: {
        todo: baseWhere,
        currentSnapshot: {
          todo_app_todo_status_id: statusMap.completed,
        },
      },
    }),

    // Pending todos
    MyGlobal.prisma.todo_app_todo_lifecycles.count({
      where: {
        todo: baseWhere,
        currentSnapshot: {
          todo_app_todo_status_id: statusMap.pending,
        },
      },
    }),

    // In-progress todos
    MyGlobal.prisma.todo_app_todo_lifecycles.count({
      where: {
        todo: baseWhere,
        currentSnapshot: {
          todo_app_todo_status_id: statusMap["in-progress"],
        },
      },
    }),

    // Overdue todos - simplified approach
    MyGlobal.prisma.todo_app_todos.count({
      where: {
        ...baseWhere,
        due_date: {
          lt: now,
        },
      },
    }),

    // Priority distribution - simplified approach
    MyGlobal.prisma.todo_app_todo_lifecycles
      .findMany({
        where: {
          todo: baseWhere,
        },
        include: {
          currentSnapshot: {
            include: {
              priority: true,
            },
          },
        },
      })
      .then((lifecycles) => {
        const distribution: IPriorityDistribution = {
          low: 0,
          medium: 0,
          high: 0,
        };

        lifecycles.forEach((lifecycle) => {
          const priorityCode = lifecycle.currentSnapshot?.priority?.code;
          if (priorityCode === "low") distribution.low++;
          else if (priorityCode === "medium") distribution.medium++;
          else if (priorityCode === "high") distribution.high++;
        });

        return distribution;
      }),

    // Recent completions (last 7 days) - simplified
    MyGlobal.prisma.todo_app_todo_snapshots.count({
      where: {
        todo_app_todo_status_id: statusMap.completed,
        snapshot_created_at: {
          gte: sevenDaysAgo,
        },
      },
    }),

    // Upcoming due dates (next 7 days) - simplified
    MyGlobal.prisma.todo_app_todos.count({
      where: {
        ...baseWhere,
        due_date: {
          gte: now,
          lte: sevenDaysLater,
        },
      },
    }),

    // Average completion time data - simplified
    MyGlobal.prisma.todo_app_todo_snapshots
      .findMany({
        where: {
          todo_app_todo_status_id: statusMap.completed,
        },
        select: {
          snapshot_created_at: true,
          todo_app_todo_id: true,
        },
      })
      .then(async (snapshots) => {
        if (snapshots.length === 0) return { totalHours: 0, count: 0 };

        let totalHours = 0;

        // Get creation times for each todo
        const todoIds = snapshots.map((s) => s.todo_app_todo_id);
        const todos = await MyGlobal.prisma.todo_app_todos.findMany({
          where: { id: { in: todoIds } },
          select: { id: true, created_at: true },
        });

        const todoMap = todos.reduce(
          (acc, todo) => {
            acc[todo.id] = todo.created_at;
            return acc;
          },
          {} as Record<string, Date>,
        );

        snapshots.forEach((snapshot) => {
          const completionTime = new Date(
            snapshot.snapshot_created_at,
          ).getTime();
          const creationTime = new Date(
            todoMap[snapshot.todo_app_todo_id],
          ).getTime();
          const hours = (completionTime - creationTime) / (1000 * 60 * 60);
          totalHours += hours;
        });

        return { totalHours, count: snapshots.length };
      }),
  ]);

  // Calculate completion rate
  const completionRate =
    totalTodos > 0 ? (completedTodos / totalTodos) * 100 : 0;

  // Calculate average completion time
  const averageCompletionTimeHours =
    averageCompletionData.count > 0
      ? averageCompletionData.totalHours / averageCompletionData.count
      : 0;

  return {
    total_todos: totalTodos,
    completed_todos: completedTodos,
    pending_todos: pendingTodos,
    in_progress_todos: inProgressTodos,
    overdue_todos: overdueTodos,
    priority_distribution: priorityDistribution,
    completion_rate: completionRate,
    average_completion_time_hours: averageCompletionTimeHours,
    recent_completions: recentCompletions,
    upcoming_due_dates: upcomingDueDates,
  };
}

