  const user = await MyGlobal.prisma.todo_app_users.findUnique({
    where: {
      id: props.user.id,
      deleted_at: null,
      status: "active",
    },
  });

  if (!user) {
    throw new HttpException("User not found or inactive", 404);
  }

  // Verify session exists and is valid
